CASES.forEach((c,i)=>{c.i=i;});
const pickList=(sim)=>{const r=sim.p.region;return CASES.filter(c=>r==='all'||c.r===r);};
const shuf=(arr,seed)=>{const a=arr.map((v,i)=>[v,i]);let s=seed*9301+49297;for(let i=a.length-1;i>0;i--){s=(s*9301+49297)%233280;const j=Math.floor(s/233280*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const sideWord=c=>c.side==='L'?'left':'right',otherWord=c=>c.side==='L'?'right':'left';
const fill=(c,t)=>{t=String(t).replace(/\{s\}/g,sideWord(c)).replace(/\{o\}/g,otherWord(c));return t.charAt(0).toUpperCase()+t.slice(1);};
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
const GRX=/\b(MOI|SxS|Tx|WB|NWB|TTP|ROM|WNL|PRICE|RTP)\b/g;
const gl=t=>esc(t).replace(GRX,m=>`<button type="button" class="ck-g" data-gl="${m}">${m}</button>`);
const F=(c,t)=>gl(fill(c,t));
