function blank(){return {step:0,asked:{},looked:false,moved:false,palp:{},tests:{},dx:null,dxSeen:false,care:null,ref:null,careSeen:false,rtp:null};}
const cur=sim=>CASES[sim.st.ci];
function setCase(sim,i){sim.st.ci=i;sim._ci=i;sim.st.w=blank();sim.infoDirty=true;}
function stepTo(sim,i){sim.st.w.step=clamp(i,0,STEPS.length-1);sim.infoDirty=true;}
function spotAt(sim,id,side){const c=cur(sim),w=sim.st.w;const k=id+(side?':'+side:'');w.palp[k]=1;}
function palpText(c,sp,side){if(sp.mid||side===c.side||c.side==='M')return c.palp[sp.id]||'No tenderness.';return 'No tenderness. This is your comparison side.';}
function win(sim){const c=cur(sim),R=REG[c.r],W=R.win,bx=0,bw=470,bt=62,bb=486,bh=bb-bt;const yr=W[1]-W[0],h=Math.min(bh/yr,bw/(2*W[2])),top=bt+(bh-yr*h)/2-W[0]*h,cx=bx+bw/2;return {cx,top,h,bt,bb,bw};}
function dotXY(w,sp,side){const sgn=side==='L'?1:side==='R'?-1:0;return {x:w.cx+sgn*sp.x*w.h,y:w.top+sp.y*w.h};}
const NEXT_HINT=['Start with how it happened. The MOI tells you which structures took the load.','Look before you touch. Compare the two sides, then watch how the athlete moves.','Start away from the sore spot, then press on it. Compare to the other side.','Choose tests that match your history and palpation. Stop if a test would stress a suspected fracture.','Commit to your best working diagnosis. It is a working one, because a physician confirms it.','Red flags first. Ask yourself what could get worse if you wait.','Decide what has to be true before this athlete goes back.'];
