 actions:[{id:'back',label:'Back a step',run(sim){stepTo(sim,sim.st.w.step-1);}},
  {id:'next',label:'Next step',primary:true,run(sim){stepTo(sim,sim.st.w.step+1);}},
  {id:'nextcase',label:'Next case',run(sim){const L=pickList(sim),i=L.findIndex(c=>c.i===sim.st.ci);setCase(sim,L[(i+1)%L.length].i);}},
  {id:'restart',label:'Start this case over',run(sim){setCase(sim,sim.st.ci);}}],
 init(sim){const i=sim._ci||0;return {ci:i,w:blank()};},
 step(){},
