  /* spots */
  R.spots.forEach((sp,i)=>{(sp.mid?[null]:['R','L']).forEach(sd=>{const p=dotXY(w,sp,sd),done=st.palp[sp.id+(sd?':'+sd:'')],hot=done&&(sp.mid||sd===c.side||c.side==='M')&&c.palp[sp.id];const r=8+3.5*k;ctx.fillStyle=hot?'#b3261e':done?'#1b7339':'#3f6fb0';ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;ctx.globalAlpha=sp.back&&!done?.75:1;ctx.beginPath();ctx.arc(p.x,p.y,r,0,6.2832);ctx.fill();ctx.stroke();ctx.globalAlpha=1;txt(ctx,String(i+1),p.x,p.y+.5,{s:11*k,w:700,c:'#ffffff',a:'center',b:'middle'});});});
  ctx.restore();
  /* the key on the right */
  const lx=w.bw+18,dy=Math.min(30*k,(420)/R.spots.length);let ly=78;txt(ctx,'Palpation points',lx,ly-12,{s:12*k,c:PAL['cv-soft'],w:700});
  R.spots.forEach((sp,i)=>{const any=Object.keys(st.palp).some(q=>q.split(':')[0]===sp.id);txt(ctx,(i+1)+'  '+sp.l+(sp.back?' (back)':''),lx,ly+8+i*dy,{s:12*k,c:any?PAL['cv-ink']:PAL['cv-soft'],w:any?700:400,b:'middle'});});
